using System;using System.Threading.Tasks;using CTXD.Client.Features.FirstPlayable;using CTXD.Client.Networking;using UnityEngine;
namespace CTXD.Client.Features.Activity { public sealed class SeasonalActivityPanel:MonoBehaviour { ApiClient _api;Action<string> _status;RectTransform _window;public static SeasonalActivityPanel Open(RectTransform host,ApiClient api,Action<string> status){var go=new GameObject("SeasonalActivityPanel");go.transform.SetParent(host,false);var p=go.AddComponent<SeasonalActivityPanel>();p._api=api;p._status=status;p.Build();_=p.Refresh();return p;}void Build(){var b=LegacyUiFactory.Panel(transform,"SeasonalBlocker",Vector2.zero,Vector2.one,new Color(0,0,0,.82f));_window=LegacyUiFactory.PixelPanel(b,"SeasonalWindow",320,100,640,500,new Color(.055f,.035f,.018f,1));}async Task Refresh(){LegacyUiFactory.DestroyChildren(_window);LegacyUiFactory.PixelLabel(_window,"SEASONAL ACTIVITIES",22,TextAnchor.MiddleCenter,new Color(1,.8f,.3f),145,15,350,35);LegacyUiFactory.PixelButton(_window,"Close",550,18,65,27,()=>Destroy(gameObject));await Dragon();await Iron();await Dstq();}async Task Dragon(){try{var v=await _api.GetDragonActivityAsync();LegacyUiFactory.PixelLabel(_window,"Dragon Boat  Score "+v.score+"  Boxes "+v.dragonNum,16,TextAnchor.MiddleLeft,Color.white,45,80,420,28);if(v.dragonNum>0)LegacyUiFactory.PixelButton(_window,"Open",485,80,100,30,async()=>{try{var r=await _api.UseDragonAsync(Guid.NewGuid().ToString("N"));_status("Dragon reward "+r.type+" +"+r.num);await Refresh();}catch(Exception e){_status(e.Message);}});}catch(Exception){LegacyUiFactory.PixelLabel(_window,"Dragon Boat inactive",16,TextAnchor.MiddleLeft,Color.gray,45,80,420,28);}}async Task Iron(){try{var v=await _api.GetIronActivityAsync();LegacyUiFactory.PixelLabel(_window,"Iron rebate  Gained "+v.iron+"  Claims "+v.rewardTimes,16,TextAnchor.MiddleLeft,Color.white,45,165,420,28);if(v.rewardTimes>0)LegacyUiFactory.PixelButton(_window,"Claim",485,165,100,30,async()=>{try{var r=await _api.ClaimIronActivityAsync(Guid.NewGuid().ToString("N"));_status("Iron +"+r.iron);await Refresh();}catch(Exception e){_status(e.Message);}});}catch(Exception){LegacyUiFactory.PixelLabel(_window,"Iron rebate inactive",16,TextAnchor.MiddleLeft,Color.gray,45,165,420,28);}}async Task Dstq(){try{var v=await _api.GetDstqActivityAsync();LegacyUiFactory.PixelLabel(_window,"DSTQ  Gold "+v.gold+"  106: "+v.ticket106+"  107: "+v.ticket107,16,TextAnchor.MiddleLeft,Color.white,45,250,540,28);LegacyUiFactory.PixelLabel(_window,v.needGold>0?v.needGold+" gold to next tier":"All tiers reached",15,TextAnchor.MiddleLeft,new Color(.9f,.8f,.55f),45,285,500,25);}catch(Exception){LegacyUiFactory.PixelLabel(_window,"DSTQ inactive",16,TextAnchor.MiddleLeft,Color.gray,45,250,420,28);}}} }
